import { useDeferredValue, useMemo, useTransition } from 'react';
export function Dashboard({ rows, query }) {
  const deferred = useDeferredValue(query);
  const [pending, startTransition] = useTransition();
  const visible = useMemo(() => filterRows(rows, deferred), [rows, deferred]);
  return renderRows(visible, pending, startTransition);
}

